export function InteractiveCard({
  title = "{{title}}",
  body = "{{body}}",
  actionLabel = "{{actionLabel}}",
  variant = "{{variant}}",
  color = "{{color}}",
}) {
  const wrap = variant === "elevated" ? { boxShadow: "0 8px 20px rgba(36,20,48,.14)" } : { border: "1.5px solid " + color };
  return (
    <article style={{ position: "relative", font: "14px/1.5 system-ui, sans-serif", color: "#241430", borderRadius: 12, padding: 18, maxWidth: 300, background: "#FAF7F2", ...wrap }}>
      <h3 style={{ margin: "0 0 8px", fontSize: 16 }}>
        {/* Stretched-link pattern: this anchor's ::after covers the card so the
            whole card is clickable, while the button below stays above it in
            z-index and is never swallowed by the overlay. */}
        <a href="#detail" style={{ color: "inherit", textDecoration: "none", position: "relative" }}>
          {title}
          <span style={{ position: "absolute", inset: 0 }} />
        </a>
      </h3>
      <p style={{ margin: "0 0 14px", fontSize: 13, opacity: 0.8 }}>{body}</p>
      <button type="button" style={{ position: "relative", zIndex: 1, border: "1.5px solid " + color, borderRadius: 8, padding: "7px 14px", fontWeight: 600, fontSize: 13, cursor: "pointer", background: "transparent", color: "#241430" }}>
        {actionLabel}
      </button>
    </article>
  );
}
